"""Prometheus metrics used by the ShikyBox application."""

from prometheus_client import Counter, Gauge, Histogram, Info


HTTP_REQUESTS = Counter(
    "shikybox_http_requests_total",
    "Total number of HTTP requests received by ShikyBox.",
    ["method", "endpoint", "status"],
)

HTTP_ERRORS = Counter(
    "shikybox_http_errors_total",
    "Total number of HTTP error responses generated by ShikyBox.",
    ["endpoint", "status"],
)

REQUEST_DURATION = Histogram(
    "shikybox_request_duration_seconds",
    "Time spent processing ShikyBox HTTP requests.",
    ["method", "endpoint"],
    buckets=(0.05, 0.1, 0.25, 0.5, 1, 2, 3, 5),
)

PRODUCT_VIEWS = Counter(
    "shikybox_product_views_total",
    "Total number of ShikyBox product-detail views.",
    ["box_type"],
)

ORDERS = Counter(
    "shikybox_orders_total",
    "Total number of successful ShikyBox orders.",
    ["box_type"],
)

ORDER_FAILURES = Counter(
    "shikybox_order_failures_total",
    "Total number of failed ShikyBox orders.",
    ["box_type", "reason"],
)

ORDERS_IN_PROGRESS = Gauge(
    "shikybox_orders_in_progress",
    "Number of ShikyBox orders currently being processed.",
)

APP_INFO = Info(
    "shikybox_app",
    "ShikyBox application build information.",
)


def initialize_app_info(environment="development", version="1.0.0"):
    """Publish static build and environment information."""
    APP_INFO.info(
        {
            "name": "ShikyBox",
            "version": version,
            "environment": environment,
        }
    )
